        setattr(cls, "OBI:0003305",
            PermissibleValue(
                text="OBI:0003305",
                title="single cell Hi-C assay",
                description="A Hi-C assay performed on a single cell.",
                meaning=OBI["0003305"]))
        setattr(cls, "OBI:0003306",
            PermissibleValue(
                text="OBI:0003306",
                title="bulk Hi-C assay",
                description="""A Hi-C assay in which the sample that is sequenced is derived from a collection of cells, such as a tissue sample or entire cell culture, and therefore provides results representative of the aggregate of sample cells.""",
                meaning=OBI["0003306"]))
        setattr(cls, "OBI:0003307",
            PermissibleValue(
                text="OBI:0003307",
                title="multi-contact Hi-C assay",
                description="""A Hi-C assay that assesses interactions between multiple DNA fragments rather than only pairwise interactions as in traditional Hi-C. The experimental procedure of cross-linking, digestion, and ligation is performed similarly to traditional Hi-C, but after DNA is purified a long-read library is produced in which many ligated fragments may be contained in a single molecule. The library is then sequenced on a long read sequencer.""",
                meaning=OBI["0003307"]))
        setattr(cls, "OBI:0003309",
            PermissibleValue(
                text="OBI:0003309",
                title="transposase-mediated analysis of chromatin looping assay",
                description="""A DNA sequencing assay designed to detect interacting genomic regions. Rather than the traditional Hi-C approach of digestion and proximity ligation, the procedure involves transposase-mediated insertion of an oligonucleotide linker between the pair of interacting regions.""",
                meaning=OBI["0003309"]))
        setattr(cls, "OBI:0003310",
            PermissibleValue(
                text="OBI:0003310",
                title="split-pool recognition of interactions and tag extension assay",
                description="""A sequencing assay designed to detect multi-way interactions between nucleic acids. The procedure involves crosslinking nuclei, and then splitting the lysate among wells in a 96-well or other multi-well plate. A different barcode is ligated to the fragments in each well, and the lysates are pooled together again. This sequence of splitting, tagging, and re-combining is repeated several times so that fragments with the same sequences of barcodes represent fragments that have co-associated throughout the experiment. Finally, a sequencing library is constructed and high-throughput sequencing is performed.""",
                meaning=OBI["0003310"]))
        setattr(cls, "OBI:0003311",
            PermissibleValue(
                text="OBI:0003311",
                title="DNA split-pool recognition of interactions and tag extension assay",
                description="""A split-pool recognition of interactions and tag extension (SPRITE) assay that only assays interactions between regions of genomic DNA.""",
                meaning=OBI["0003311"]))
        setattr(cls, "OBI:0003312",
            PermissibleValue(
                text="OBI:0003312",
                title="RNA-DNA split-pool recognition of interactions and tag extension assay",
                description="""A split-pool recognition of interactions and tag extension (SPRITE) assay in which RNA in the cross-linked complexes is converted to cDNA before the initial splitting step, allowing analysis of RNA-DNA interactions.""",
                meaning=OBI["0003312"]))
        setattr(cls, "OBI:0003313",
            PermissibleValue(
                text="OBI:0003313",
                title="genome architecture mapping assay",
                description="""A DNA sequencing assay designed to analyze 3D chromatin structure without relying on digestion and ligation. The procedure involves cryosectioning samples in random orientation, and then single nuclear profiles are isolated by laser microdissection. Each nuclear profile then undergoes high-throughput sequencing, and subsequent analysis can generate a matrix of inferred proximity between genomic regions.""",
                meaning=OBI["0003313"]))
        setattr(cls, "OBI:0003314",
            PermissibleValue(
                text="OBI:0003314",
                title="mapping RNA-genome interactions assay",
                description="""A nuclear ligation assay for probing RNA-DNA interactions in the nucleus. Nuclei are crosslinked, and RNA fragments are ligated to proximal DNA fragments via a special linker molecule. After reverse transcription, high-throughput sequencing is performed.""",
                meaning=OBI["0003314"]))
